<script lang="ts">
 import {tr as t} from '../services/preferences';import {auditCase} from '../services/case-audit';
 export let cases:any[],stages:any[],methods:Record<string,any>;export let onadd:(id:string)=>void;
 let group='';
 $: scenes=stages.flatMap(st=>st.scenes.map((s:any)=>({...s,stageId:st.id,stageName:st.name})));
 $: pending=scenes.filter(s=>!cases.some(c=>c.manifest.sceneId===s.id));
 $: issues=cases.map(c=>({c,checks:auditCase(c,scenes,methods)}));
</script>
<details class="case-status-panel"><summary>{$t('接入检查与待补充场景')}<span>{scenes.length-pending.length} / {scenes.length} {$t('场景已覆盖')}</span></summary><div class="registry-content"><p>{$t('检查案例绑定、三个内容部分和演示入口。缺少流程或演示会显示提醒，不会阻止仅背景案例接入。')}</p><div class="registry-table-scroll"><table><thead><tr><th>{$t('案例')}</th><th>{$t('专业背景')}</th><th>{$t('案例流程')}</th><th>{$t('案例演示')}</th><th>{$t('接入检查')}</th></tr></thead><tbody>{#each issues as {c,checks}}<tr><th><a href={'#/scene/'+c.manifest.sceneId+'?case='+c.id}>{c.manifest.title} ↗</a></th>{#each ['background','workflow','demo'] as key}<td>{c.manifest.tabs[key]?'●':'○'}</td>{/each}<td><details><summary>{checks.some(c=>c.level==='error')?$t('需修复'):checks.some(c=>c.level==='warn')?$t('有提醒'):$t('通过')}</summary>{#each checks as check}<p class:error={check.level==='error'}>{check.level==='ok'?'✓':check.level==='warn'?'!':'×'} {$t(check.detail)}</p>{/each}</details></td></tr>{/each}</tbody></table></div><div class="registry-pending-heading"><h3>{#if pending.length}{pending.length} {$t('个场景等待案例')}{:else}{$t('全部场景均已有可运行案例。')}{/if}</h3><select aria-label={$t('筛选待接入环节')} bind:value={group}><option value="">{$t('全部环节')}</option>{#each stages as st}<option value={st.id}>{st.name}</option>{/each}</select></div><div class="pending-scene-index">{#each pending.filter(s=>!group||s.stageId===group) as scene}<div><a href={'#/scene/'+scene.id}><small>{scene.stageName}</small>{scene.name} ↗</a><button onclick={()=>onadd(scene.id)}>{$t('添加案例')} ＋</button></div>{/each}</div></div></details>
